L000428	\subsection*{Thermodynamic Bethe Ansatz}
L000429	The Floquet propagator $\mathcal{U}=\mathcal{U}(\tau;\Delta)$ of the Trotterized XXZ circuit with axial anisotropy $\Delta>1$ and timestep $\tau \in \mathbb{R}_{+}$ can be diagonalized using Bethe Ansatz.
L000430	The Hamiltonian limit, Eq.~\eqref{eq_Ham}, is retrieved by taking $\tau\to 0$.
L000431	Here we only gather the main formulae and refer the reader to Refs.~\cite{Vernier_2023,Zadnik_2024} for details.
L000432	
L000433	The excitation spectrum consists of magnons and their bound states. The dispersion relation of unbound magnons is encoded in the Floquet quasimomentum $p(u)$ and quasienergy $E(u)$, reading
L000434	\begin{align}
L000435	    e^{-2\ii p(u)} = \frac{\sin{(u_{+}+\ii \eta/2)}}{\sin{(u_{+}-\ii \eta/2)}}
L000436	    \frac{\sin{(u_{-}+\ii \eta/2)}}{\sin{(u_{-}-\ii \eta/2)}},\\
L000437	     e^{2\ii E(u)} = \frac{\sin{(u_{+}-\ii \eta/2)}}{\sin{(u_{+}+\ii \eta/2)}}
L000438	    \frac{\sin{(u_{-}+\ii \eta/2)}}{\sin{(u_{-}-\ii \eta/2)}}.
L000439	\end{align}
L000440	Circuit anisotropy $\eta$ and spectral shift $\delta=\delta(\tau)$, entering through $u_{\pm} \equiv u\pm \delta/2$, are determined via parameter transmutation relations
L000441	\begin{align}
L000442	    \cosh \eta = \frac{\sin{(\Delta \tau/2)}}{\sin{(\tau/2)}},\quad
L000443	    \sin{(\delta)} = \tan{(\tau/2)} \sinh \eta.
L000444	\end{align}
L000445	In the thermodynamic limit, $n$-magnon bound states with $n\in \mathbb{N}$ become well-defined asymptotic excitations. Grouping the quantum labels, $\underline{u}\equiv (n,u)$, with $u\in [-\pi/2,\pi/2)$, their quasimomenta and quasienergies, denoted by $p_{\underline{u}}$ and $E_{\underline{u}}$, respectively, are obtained by the fusion of elementary magnons. In terms of $K_{n}(u)\equiv\tfrac{1}{2\pi}\tfrac{2\sinh{(n\eta)}}{\cosh{(n\eta)}-\cos{(2u)}}$, they take the form $p_{\underline{u}}=\tfrac{1}{2}(K_{n}(u_{+})+K_{n}(u_{-}))$
L000446	and $E_{\underline{u}}=\tfrac{1}{2}(K_{n}(u_{+})-K_{n}(u_{-}))$.
L000447	
L000448	Equilibrium macrostates are fully specified by the Fermi occupation functions $\vartheta_{\underline{u}}\equiv \rho_{\underline{u}}/\rho^{\rm tot}_{\underline{u}}$, where the quasiparticle rapidity densities $\rho_{\underline{u}}$ and the total state densities $\rho^{\rm tot}_{\underline{u}}(u)$ are related via
L000449	\begin{equation}\label{eq:Bethe_Yang}
L000450	    \rho^{\rm tot}_{\underline{u}}=\frac{1}{2\pi}\partial_{u} p_{\underline{u}}+
L000451	    \mathcal{T}_{\underline{u}}^{~\underline{u'}}\rho_{\underline{u'}},
L000452	\end{equation}
L000453	with the summation convention over the repeated discrete index and convolution over the domain of the common rapidity variable in mind.
L000454	The scattering kernel $\mathcal{T}_{\underline{u}}^{~\underline{u'}}\equiv -\mathcal{K}_{n,n'}(u-u')$ decomposes as
L000455	\begin{equation}
L000456	    \mathcal{K}_{n,n'}(u)=\frac{1}{2\pi}\sum_{m=|n-n'|/2}^{(n+n')/2+1}\!(\partial_{u}p_{2m}(u)+\partial_{u}p_{2m+2}(u)).
L000457	\end{equation}
L000458	Equation \eqref{eq:Bethe_Yang} is physically understood as the dressing of bare momenta $p_{\underline{u}}$ due to elastic scattering with other excitations. Introducing the dressing operation
L000459	\begin{equation}
L000460	    g_{\underline{u}}^{\rm dr} = [R^{-\mathrm{T}}]_{\underline{u}}^{~\underline{u'}}g_{\underline{u'}},\qquad R \equiv 1-\vartheta\mathcal{T},
L000461	\end{equation}
L000462	for any dummy functions $g_{\underline{u}}$, Eq.~\eqref{eq:Bethe_Yang} reads simply $2\pi\rho^{\rm tot}_{\underline{u}}=(\partial_{u}p_{\underline{u}})^{\rm dr}=[R^{-\mathrm{T}}]_{\underline{u}}^{~\underline{u'}}\partial_{u}p_{\underline{u}}$.
L000463	
L000464	We consider grand canonical equilibrium states $\hat{\varrho}\simeq e^{\mu \hat{S}^{z}}/Z$ \ch{where dressed quantities can be computed analytically}. The corresponding macrostates, which do not depend on the quasiparticle dispersion laws, read explicitly $\vartheta_{n}(u)=1/\mathcal{X}^{2}_{n}(\mu)$ with $\mathcal{X}_{n}(\mu) \equiv \frac{\sinh{((n+1)\mu/2)}}{\sinh{(\mu/2)}}$. On the other hand, the effective velocities of bound states, $v^{\rm eff}_{\underline{u}}\equiv \partial_{u} E_{\underline{u}}/\partial_{u} p_{\underline{u}}$, do depend on the timestep $\tau$,
L000465	\begin{equation}
L000466	    v^{\rm eff}_{\underline{u}}(\tau) = \frac{\rho^{(0)\rm tot}_{n}(u_{+})-\rho^{(0)\rm tot}_{n}(u_{-})}{\rho^{(0)\rm tot}_{n}(u_{+})+\rho^{(0)\rm tot}_{n}(u_{-})},
L000467	\end{equation}
L000468	where $\rho^{(0)\rm tot}_{n}(u)$ denote the total state densities of the \emph{homogeneous} Hamiltonian spin chain, Eq.~\eqref{eq_Ham}, reading
L000469	\begin{equation}
L000470	    \rho^{(0)\rm tot}_{n}(u) = \frac{\mathcal{X}_{n}(\mu)}{\mathcal{X}_{1}(\mu)}
L000471	    \left(\frac{K_{n}(u)}{\mathcal{X}_{n-1}(\mu)}-\frac{K_{n+2}(u)}{\mathcal{X}_{n-1}(\mu)}\right).
L000472	\end{equation}
L000473	Away from half-filling, i.e.~for $\mu\neq 0$, the second cumulant $c_{2}(T)$ of magnetization transfer (i.e.~the Drude self-weight) exhibits linear asymptotic growth with time $T$, $c_{2}(T)\simeq s_{2}\sqrt{T}$, with
L000474	\begin{equation}
L000475	    s_{2} = \sum_{\underline{u}}\rho^{\rm tot}_{\underline{u}}\vartheta_{\underline{u}}(1-\vartheta_{\underline{u}})|\veff_{\underline{u}}|(m^{\rm dr}_{\underline{u}}(\mu))^{2},
L000476	\end{equation}
L000477	where $m^{\rm dr}_{n}(\mu) \equiv \partial_{\mu}\log{(\mathcal{X}^{2}_{n}(\mu)-1)}$ represents the dressed magnetization of the quasiparticles. Since $\lim_{\mu \to 0}m^{\rm dr}_{n}=0$, $s_{2}$ vanishes at half-filling with the curvature
L000478	\begin{equation}
L000479	    \lim_{\mu\to 0}\partial^{2}_{\mu}s_{2}(\mu) = \sum_{\underline{u}}\rho^{\rm tot}_{\underline{u}}\vartheta_{\underline{u}}(1-\vartheta_{\underline{u}})|\veff_{\underline{u}}|\mathfrak{m}_{\underline{u}}^{2},
L000480	\end{equation}
L000481	where
L000482	\begin{equation}\label{eqn:frakm}
L000483	    \mathfrak{m}_{\underline{u}}=\lim_{\mu \to 0}\partial_{\mu}m^{\rm dr}_{\underline{u}}(\mu)=\frac{1}{6}(n+1)^{2}.
L000484	\end{equation}
L000485	
L000486	\subsection{Numerical simulations}
L000487	To test our predictions, we have performed extensive numerical simulations of the integrable Trotterization of the XXZ spin chain \cite{Vanicat2017,Ljubotina2019}, with the Floquet propagator
L000488	\begin{equation}
L000489	    \mathcal{U}(\tau) = \prod_{\ell = 1}^{L/2} U_{2\ell-1, 2\ell}
L000490	    \prod_{\ell = 1}^{L/2} U_{2\ell, 2\ell+1},
L000491	\end{equation}
L000492	with $U_{\ell, \ell+1} = \exp{[-\ii \tfrac{\tau}{4}(\hat{\sigma}^x_\ell\hat{\sigma}^x_{\ell+1}+\hat{\sigma}^y_\ell\hat{\sigma}^y_{\ell+1}+\Delta \hat{\sigma}^z_\ell\hat{\sigma}^z_{\ell+1})]}$ and time step $\tau \in \mathbb{R}_+$.
L000493	We used the quantum generating function approach introduced in Ref.~\cite{Valli_2025} which expresses the generating function as a product of operators
L000494	\begin{equation}
L000495	\langle e^{\lambda \hat{J}(t)} \rangle = 2^{-L} {\rm Tr}\, \left[ \hat \Lambda(\lambda, t) \hat \Lambda(-\lambda, 0)\right], \label{eq:QGF}
L000496	\end{equation}
L000497	where $\hat \Lambda (\lambda,t=n\tau) = \mathcal{U}^n(\tau) \hat \Lambda(\lambda, 0)\, [\mathcal{U}^n(\tau)]^\dagger$ is a time-evolved operator and $\hat \Lambda(\lambda, 0) = \bigotimes_{\ell = 1}^{L} e^{\lambda_\ell \hat{\sigma}^z_\ell/2}$ with $\lambda_\ell = \lambda \in \mathbb{R}$ for $1 \leq \ell \leq L/2$ and $\lambda_\ell = 0$ otherwise.
L000498	The tensor network simulations were performed using the Julia implementation of the ITensor library \cite{itensor,itensor-r0.3} with maximal bond dimension $\chi = 2^8$ on a chain of length $L = 2^8$ for times up to $t_{\rm max}=2^7$. The estimation and extrapolation of the variance of the integrated spin current from the generating function \eqref{eq:QGF} is reported in the Supplementary Material \cite{SM}.
L000499	
