L000502	\subsection{Fluctuating spin velocity}
L000503	We first note that the fluctuating spin velocity $v(x,t)=j_0(x,t)/q_0(x,t)$ is also given by $v(x,t)=\tilde{\jmath}_0(x,t)/\tilde{q}_0(x,t)$ where $\tilde{q}_0=\frac{1}{2}-\sum_{\underline{u}}n\rho_{\underline{u}}$ and $\tilde{\jmath}_0=\sum_{\underline{u}}n\rho_{\underline{u}}\bveff_{\underline{u}}[\rho]$, which follows from the fact that both $q_0$ and $j_0$ include the sign of magnetization, which cancel out in $v$. We first focus on fluctuations of the current $\tilde{\jmath}_0$. Noting that $\tilde{\jmath}_0$ can also be written as $\tilde{\jmath}_0=\sum_{\underline{u}}\frac{n}{2\pi}(E')^{\mathrm{dr}}_{\underline{u}}[\bar{\vartheta}]\vartheta_{\underline{u}}$ and we know that $\vartheta_{\underline{u}}(x,t)$ fluctuates as Eq.~\eqref{eq:fluc_filling}, we only need to understand the way $(E')^{\mathrm{dr}}_{\underline{u}}(x,t)=(E')^{\mathrm{dr}}_{\underline{u}}[\vartheta_\cdot(x,t)]$ fluctuates. Given that
L000504	\begin{align}
L000505	    &(E')^{\mathrm{dr}}_{\underline{u}}(x,t)\simeq E_{\underline{u}}'+\mathcal{T}_{\underline{u}}^{~\underline{u'}}\bar{\vartheta}_{\underline{u'}}(E')^{\mathrm{dr}}_{\underline{u'}}(x,t)\n
L000506	&\quad+T^{-\frac{1}{4}}\mathcal{T}_{\underline{u}}^{~\underline{u'}}\delta\vartheta_{\underline{u'}}(x-\sqrt{\tau}\bveff_{\underline{u'}}t,0)(E')^{\mathrm{dr}}_{\underline{u'}}(x,t),
L000507	\end{align}
L000508	defining $(E')^{\mathrm{dr}}_{\underline{u}}(x,t)\simeq  ( E')^{\mathrm{dr}}_{\underline{u}}+T^{-1/4}\delta(E')^{\mathrm{dr}}_{\underline{u}}(x,t)$, we have
L000509	\begin{align}
L000510	\delta(E')^{\mathrm{dr}}_{\underline{u}}&=\mathcal{T}_{\underline{u}}^{~\underline{u'}}(\bar{\vartheta}_{\underline{u'}} \delta(E')^{\mathrm{dr}}_{\underline{u'}}+\delta\vartheta_{\underline{u'}}(x-\sqrt{T}\bveff_{\underline{u'}}t,0)(E')^{\mathrm{dr}}_{\underline{u'}})\n
L000511	    &=(\delta\mathcal{E}(x,t))_{\underline{u}}^\mathrm{dr},
L000512	\end{align}
L000513	where $\delta\mathcal{E}_{\underline{u}}(x,t)=\mathcal{T}_{\underline{u}}^{~\underline{u'}}\delta\vartheta_{\underline{u'}}(x-\sqrt{T}\bveff_{\underline{u'}}t,0)(E')^{\mathrm{dr}}_{\underline{u'}}$. Using these, a simple calculation with the aid of the identity $1+\vartheta \mathcal{T}^\dr=R^{-1}$ yields the fluctuating current $\tilde{\jmath}_0(x,t)$
L000514	\begin{equation}
L000515	     \tilde{\jmath}_0(x,t)\simeq\frac{T^{-1/4}}{2\pi}\sum_{\underline{u}}n^\mathrm{dr}_{\underline{u}}(E')^{\mathrm{dr}}_{\underline{u}}\delta\vartheta_{\underline{u}}(x-\sqrt{T}\bveff_{\underline{u}}t,0).
L000516	\end{equation}
L000517	Now we make an important observation: the dressed magnetization, which exactly vanishes at half-filling by symmetry, behaves for small $\mu$ as $m^\mathrm{dr}_{\underline{u}}= \mathfrak{m}_{\underline{u}}\mu + O(\mu^{2})$. For instance, at infinite temperature $\mathfrak{m}_{\underline{u}}$ is given by Eq.~\eqref{eqn:frakm}. Assuming that this replacement is valid in the sum (i.e. the sum over $n$ is convergent upon the replacement), the current $\tilde{\jmath}_0(x,t)$ near $\mu=0$ thus behaves as
L000518	\begin{equation}
L000519	\tilde{\jmath}_0(x,t)\simeq\frac{T^{-1/4}\mu}{2\pi}\sum_{\underline{u}}\mathfrak{m}_{\underline{u}}(E')^{\mathrm{dr}}_{\underline{u}}\delta\vartheta_{\underline{u}}(x-\sqrt{T}\bveff_{\underline{u}}t,0).
L000520	\end{equation}
L000521	We generically expect that the linear decrease of $\tilde{\jmath}_0(x,t)$ in $\mu$ near half-filling is precisely canceled out when considering the fluctuating velocity $v=\tilde{\jmath}_0/\tilde{q}_0$, where $\tilde{q}_0$ fluctuates as $\tilde{q}_0(x,t)\simeq\tilde{\mathsf{q}}_0+T^{-1/4}\delta\tilde{q}_0(x,t)$ with $\tilde{\mathsf{q}}_0=\frac{1}{2}-\sum_{\underline{u}}n\rho_{\underline{u}}$. This is because near half-filling $\tilde{\mathsf{q}}_0$ behaves as $\tilde{\mathsf{q}}_0\sim \mathsf{C}_\mathrm{s} \mu$, where $\mathsf{C}_\mathrm{s}$ is the spin susceptibility, by definition. Indeed, again at infinite temperature, we can demonstrate that the density $\tilde{\mathsf{q}}_0$ is given by $\tilde{\mathsf{q}}_0=\tfrac{1}{2}\tanh{(h/2)}$, which implies $\mathsf{C}_\mathrm{s}=1/4$.
L000522	
L000523	Combining these, at half-filling, we conclude that the velocity $v(x,t)$ fluctuates as Eq.~\eqref{eq:vel_fluctuation}.
L000524	
L000525	\subsection{Moment generating function}
L000526	To perform the path integral Eq.~\eqref{eq:generating_function}, we first integrate over the initial charge \ch{fluctuation} $\delta q_0(x,0)$. \ch{The relevant part of the path integral is evaluated as (using Eq.~\eqref{eq_curr_fluct})
L000527	
L000528	\begin{align}
L000529	    &\frac{1}{2\pi}\int\mathcal{D}\delta q_0(\cdot,0)\exp\left[\lambda J(T) - \int\dd \Tx \frac{(\delta q_0(\Tx,0))^2}{2\mathsf{C}_{00}} \right] \n
L000530	    &=e^{\frac{1}{2}\mathsf{C}_{00}\lambda^2T^{1/2}|X(1)|}.
L000531	\end{align}}
L000532	Plugging this back to Eq.~\eqref{eq:generating_function}, we thus have
L000533	\begin{align}\label{eq:theta_integral}
L000534	    \langle e^{\lambda J(T)}\rangle&=\frac{1}{\sqrt{2\pi}}\int\mathcal{D}\delta\vartheta(\cdot,0) e^{-\frac{1}{2}\sum_{\underline{u}:n<\Lambda}\int\dd x\,(\delta\vartheta_{\underline{u}}(x,0))^2}\n
L000535	    &\quad\times e^{|\sum_{\underline{u}}\int\dd x\,a_{\underline{u}}(x)\delta\vartheta_{\underline{u}}(x,0))|},
L000536	\end{align}
L000537	where
L000538	
L000539	\begin{equation}
L000540	    a_{\underline{u}}(x)=\frac{T^{1/4}\lambda^2}{2}\sqrt{\chi_{\underline{u}}}\mathfrak{m}_{\underline{u}}\mathrm{sgn}(\bveff_{\underline{u}})\mathbf{1}_{A}(x)
L000541	\end{equation}
L000542	with $A \equiv (-\sqrt{T}|\bveff_{\underline{u}}|,0)$. \ch{Importantly, the sum $\sum_{\underline{u}:n<\Lambda}$ can be now extended to the unrestricted one as the contribution from $n=\infty$ is exponentially suppressed due to $\bveff_{\underline{u}}\sim e^{-n\eta}$.}
L000543	The path-integral in Eq.~\eqref{eq:theta_integral} then reduces to a one-dimensional integral \cite{Yoshimura2025}, which reads
L000544	\begin{equation}
L000545	    \langle e^{\lambda J(T)}\rangle\simeq \frac{1}{\sqrt{2\pi}}\int dX\,e^{-\frac{1}{2}X^2}e^{\sqrt{2}\xi^2|X|}=e^{\xi^4}(1+\mathrm{erf}\,\xi^2)
L000546	\end{equation}
L000547	where $\xi^2=\lambda^2\sigma\sqrt{T/8}$ and $\sigma^2=\sum_{\underline{u}}(\mathfrak{m}_{\underline{u}})^2\chi_{\underline{u}}|\bveff_{\underline{u}}|$.
