L000611	\section{Spin diffusion constant}
L000612	We define the Onsager matrix via the Green-Kubo formula
L000613	\begin{equation}\label{eq:onsager}
L000614	    L_{ij}=\int_\mathbb{R}\dd t\left(\int_\mathbb{R}\dd x\langle \hat{\jmath}_i(x,t)\hat{\jmath}_j(0,0)\rangle^c-\mathsf{D}_{ij}\right),
L000615	\end{equation}
L000616	where $\mathsf{D_{ij}}=\lim_{t\to\infty}\int_\mathbb{R}\dd x\langle \hat{\jmath}_i(x,t)\hat{\jmath}_j(0,0\rangle^c$ is the Drude weight. The Einstein relation then relates this to the diffusion matrix through $L=D\mathsf{C}$. To compute the spin diffusion constant $D_\mathrm{s}=D_{00}$ at half-filling where the spin Drude weight $\mathsf{D}_{00}$ vanishes, we first note that $\mathsf{C}_{i0}=\mathsf{C}_\mathrm{s}\delta_{0i}$ holds there, implying ${L}_{00}=D_\mathrm{s}\mathsf{C}_\mathrm{s}$. We therefore need to evaluate ${L}_{00}$ only. While it is straightforward to directly compute Eq.~\eqref{eq:onsager}, we shall deal with another equivalent representation of it
L000617	\begin{equation}
L000618	  L_{00}= \lim_{t\to\infty}\frac{1}{t}\int_\mathbb{R}\dd x\,x^2\langle \hat{q}_0(x,t)\hat{q}_0(0,0)\rangle^c,
L000619	\end{equation}
L000620	as we wish to demonstrate how the spin-spin correlator $\langle \hat{q}_0(x,t)\hat{q}_0(0,0)\rangle^c$ behaves at the diffusive scale first.
L000621	To this end, we focus on evaluating $\langle q_0(x,t) q_0(0,0)\rangle^c$, in terms of which the spin Onsager coefficient reads
L000622	\begin{equation}\label{eq:ons}
L000623	   L_{00}=  \lim_{T\to\infty}\sqrt{T}\lim_{t\to\infty}\frac{1}{t}\int_\mathbb{R}\dd x\,x^2\langle q_0(x,t) q_0(0,0)\rangle^c.
L000624	\end{equation}
L000625	Let us start with noticing that one path-integral involved in evaluating $\langle q_0(x,t) q_0(0,0)\rangle^c$ can be performed immediately: since we have $\langle q_0(x,t) q_0(0,0)\rangle=T^{-1/2}\langle \delta q_0(x-X(t),0) \delta q_0(0,0)\rangle$, the path-integral over $\delta q_0(x,0)$ can be taken first using $\langle \delta q_0(x,0) \delta q_0(y,0)\rangle=\mathsf{C}_\mathrm{s}\delta(x-y)$, yielding
L000626	\begin{equation}
L000627	    \label{eq:qq_asymp1}
L000628	    \langle q_0(x,t) q_0(0,0)\rangle^c \simeq \frac{T^{-\frac{1}{2}}\mathsf{C}_\mathrm{s}}{(2\pi)^\frac{3}{2}}\int\mathcal{D}\delta\vartheta(\cdot,0)\int\dd k\,e^{\ii k(x-X(t))}\exp\left[-\sum_{\underline{u}}\int\dd x\frac{(\delta\vartheta_{\underline{u}}(x,0))^2}{2\sigma^2_{\underline{u}}}\right].
L000629	\end{equation}
L000630	Plugging $X(t)\simeq \frac{T^{-1/4}}{2\pi\mathsf{C}_\mathrm{s}}\sum_{\underline{u}}\mathfrak{m}_{\underline{u}}(p')^\mathrm{dr}_{\underline{u}}\int_{-\sqrt{T}t\bar{v}^\eff_{\underline{u}}}^0\dd x\,\delta\vartheta_{\underline{u}}(x,0)$ into Eq.~\eqref{eq:qq_asymp1}, trivial Gaussian integrals give
L000631	\begin{equation}
L000632	     \langle q_0(x,t) q_0(0,0)\rangle^c\simeq \frac{T^{-\frac{1}{2}}\mathsf{C}_\mathrm{s}}{\sqrt{2\pi D_\mathrm{s}t}}e^{-x^2/2D_\mathrm{s}t},
L000633	\end{equation}
L000634	where $D_\mathrm{s}=\mathsf{C}^{-2}_\mathrm{s}\sum_{\underline{u}}\mathfrak{m}^2_{\underline{u}}\chi_{\underline{u}}|\bar{v}^\eff_{\underline{u}}|=\mathsf{C}^{-2}_\mathrm{s}\sigma^2$ is identified with the spin diffusion constant. We can readily verify it by evaluating Eq.~\eqref{eq:ons}, which confirms $L_{00}=D_\mathrm{s}\mathsf{C}_\mathrm{s}$ as anticipated.
